    [0, 0, 0, 5, 0],
    [0, 5, 5, 5, 5],
    [5, 5, 0, 0, 0],
    [0, 5, 0, 0, 0]
]

reachable_orth = flood_fill_boundary(demo_input)
reachable_diag = flood_fill_diagonal(demo_input)

print("Cells that became 8 or 7 in demo output:")
changed_cells = [
